    val SESSION_QUOTES: List<SessionQuote> by lazy {
        RAW_QUOTES.map { q ->
            val style = when (q.number % 3) {
                1 -> "editorial"
                2 -> "calligraphy"
                else -> "classic"
            }
            SessionQuote(
                id = String.format("quote_%03d", q.number),
                text = q.text,
                author = q.author,
                category = q.category,
                fontStyle = style,
                active = true,
                typingSpeedMs = 28L
            )
        }
    }

    val FOCUS_QUOTES: List<FocusQuote> by lazy {
        RAW_QUOTES.map { q ->
            val cat = when (q.category.lowercase()) {
                "reading", "deep study", "books" -> QuoteCategory.STUDY
                "discipline", "time" -> QuoteCategory.DISCIPLINE
                "exam prep", "exams" -> QuoteCategory.EXAMS
                "consistency" -> QuoteCategory.CONSISTENCY
                "motivation", "courage", "future" -> QuoteCategory.MOTIVATION
                else -> QuoteCategory.FOCUS
            }
            FocusQuote(
                id = q.number,
                text = q.text,
                author = q.author,
                category = cat
            )
        }
    }
